class Keyframe {
  const Keyframe({required this.b, this.h, required this.p, this.r, required this.t});

  factory Keyframe.fromJson(Object? json) {
    final r = JsonReader(json, 'Keyframe');
    return Keyframe(
      b: r.list('b', JsonReader.intOf),
      h: r.intOrNull('h'),
      p: r.map('p', JsonReader.anyOf),
      r: r.listOrNull('r', JsonReader.anyOf),
      t: r.int_('t'),
    );
  }

  /// The ball: x, y and its height
  final List<int> b;

  /// The player on the ball; null while it is in flight (a pass or a shot, Sprint 33 B1)
  final int? h;

  /// Every player on the pitch by id, his x and y
  final Map<String, Object?> p;

  /// [Sprint 31 D1] The officials: the referee, the far assistant (outside the far touchline, right half) and the near one (outside the near touchline, left half). They follow the ball only. Older recordings have none
  final List<Object?>? r;

  /// Its place among the minute's Keyframes from 0: six, or ten in a minute with a chance, a corner, a free kick, a penalty or a goal (Sprint 32 R4)
  final int t;
}

